30	import org.springframework.samples.petclinic.model.MemberId;
31	import org.springframework.samples.petclinic.model.MembershipLevel;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.PossibleDuplicate;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        LocalDate registrationDate = BusinessDay.adjust(
110	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
111	        owner.setRegistrationDate(registrationDate);
112	        Collection<Owner> owners = this.clinicService.findAllOwners().stream().filter(existing -> !existing.isDeleted()).toList();
113	        if (owners.stream().filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() >= 100) {
114	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
115	        }
116	        if (owners.stream().anyMatch(existing -> existing.getIdentityKey().equals(owner.getIdentityKey()))
117	                || owners.stream().filter(existing -> existing.getCity().equalsIgnoreCase(owner.getCity())).count() >= 50) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        owner.setNamesakeCount((int) owners.stream()
121	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(owner.getFirstName())
122	                && existing.getLastName().equalsIgnoreCase(owner.getLastName()))
123	            .count());
124	        owner.setHouseholdMemberCount(1 + (int) owners.stream().filter(existing -> sameHousehold(existing, owner)).count());
125	        owner.setMemberId(MemberId.of(owner, owners));
126	        Integer possibleDuplicateOf = PossibleDuplicate.of(owner, owners);
127	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
128	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
129	        owner.setCapacityWarning(owners.stream()
130	            .filter(existing -> existing.getCity().equalsIgnoreCase(owner.getCity())).count() >= 40);
131	        this.clinicService.saveOwner(owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        int householdMax = owners.stream().filter(existing -> sameHousehold(existing, owner))
134	            .mapToInt(existing -> MembershipLevel.of(MembershipLevel.points(existing.getNamesakeCount(),
135	                existing.getEmail(), existing.getHouseholdMemberCount(), existing.getRegistrationDate())))
136	            .max().orElse(-1);
137	        if (householdMax >= 0 && ownerDto.getMembershipLevel() > householdMax + 1) {
138	            ownerDto.setMembershipLevel(householdMax + 1);
139	        }
140	        ownerDto.setBulkSignupWarning(owners.stream()
141	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() > 80);
142	        headers.setLocation(UriComponentsBuilder.newInstance()
143	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
144	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
145	    }
146	
147	    /** Two owners share a household when they resolve to the same {@link Owner#getHouseholdId()}
148	     *  (matching last name and postcode). */
149	    private static boolean sameHousehold(Owner a, Owner b) {
150	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
156	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
157	        if (currentOwner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        currentOwner.setAddress(ownerFieldsDto.getAddress());
161	        currentOwner.setCity(ownerFieldsDto.getCity());
162	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
163	        currentOwner.setLastName(ownerFieldsDto.getLastName());
164	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
165	        this.clinicService.saveOwner(currentOwner);
166	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Transactional
171	    @Override
172	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        owner.setDeleted(true);
178	        this.clinicService.saveOwner(owner);
179	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        HttpHeaders headers = new HttpHeaders();
190	        Pet pet = petMapper.toPet(petFieldsDto);
191	        owner.setId(ownerId);
192	        pet.setOwner(owner);
193	        pet.getType().setName(null);
194	        this.clinicService.savePet(pet);
195	        PetDto petDto = petMapper.toPetDto(pet);
196	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
197	            .buildAndExpand(pet.getId()).toUri());
198	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
204	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
205	        if (currentOwner != null) {
206	            Pet currentPet = this.clinicService.findPetById(petId);
207	            if (currentPet != null) {
208	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
209	                currentPet.setName(petFieldsDto.getName());
210	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
211	                this.clinicService.savePet(currentPet);
212	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
221	        HttpHeaders headers = new HttpHeaders();
222	        Visit visit = visitMapper.toVisit(visitFieldsDto);
223	        Pet pet = new Pet();
224	        pet.setId(petId);
225	        visit.setPet(pet);
226	        this.clinicService.saveVisit(visit);
227	        VisitDto visitDto = visitMapper.toVisitDto(visit);
228	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
229	            .buildAndExpand(visit.getId()).toUri());
230	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
231	    }
232	
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner != null) {
239	            Pet pet = owner.getPet(petId);
240	            if (pet != null) {
241	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
242	            }
243	        }
244	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	    }
246	}
