16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	@EntityListeners(OwnerAuditListener.class)
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Transient
44	    private String flatAddress;
45	
46	    @Transient
47	    private String addressLine1;
48	
49	    @Transient
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date", columnDefinition = "DATE")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date", columnDefinition = "DATE")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String memberId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "household_member_count")
80	    private Integer householdMemberCount;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @Column(name = "capacity_warning")
89	    private Boolean capacityWarning;
90	
91	    @Column(name = "deleted")
92	    private boolean deleted;
93	
94	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
95	    private Set<Pet> pets;
96	
97	    /** Default an absent registration date to the server's current date on first persist. */
98	    @PrePersist
99	    void defaultRegistrationDate() {
100	        if (this.registrationDate == null) {
101	            this.registrationDate = LocalDate.now();
102	        }
103	    }
104	
105	    public LocalDate getRegistrationDate() {
106	        return this.registrationDate;
107	    }
108	
109	    public void setRegistrationDate(LocalDate registrationDate) {
110	        this.registrationDate = registrationDate;
111	    }
112	
113	    public LocalDate getBirthDate() {
114	        return this.birthDate;
115	    }
116	
117	    public void setBirthDate(LocalDate birthDate) {
118	        this.birthDate = birthDate;
119	    }
120	
121	    /** Unified member identifier formatted {@code <REGION><FY><HASH8><CHK>} (see {@link MemberId}). */
122	    public String getMemberId() {
123	        return this.memberId;
124	    }
125	
126	    /** Stable identifier shared by owners of the same household (matching last name and postcode). */
127	    @Transient
128	    public String getHouseholdId() {
129	        return HouseholdId.of(getLastName(), this.postcode);
130	    }
131	
132	    public void setMemberId(String memberId) {
133	        this.memberId = memberId;
134	    }
135	
136	    /** Derived duplicate-detection key: the SHA-256 hex over the normalized telephone, lower-case
137	     *  email and soundex of the last name (see {@link IdentityKey}). Two owners are duplicates only
138	     *  when this whole key matches, so a differing telephone alone breaks the collision. */
139	    @Transient
140	    public String getIdentityKey() {
141	        return IdentityKey.of(this.telephone, this.email, getLastName());
142	    }
143	
144	    public Integer getNamesakeCount() {
145	        return this.namesakeCount;
146	    }
147	
148	    public void setNamesakeCount(Integer namesakeCount) {
149	        this.namesakeCount = namesakeCount;
150	    }
151	
152	    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
153	     *  captured when the owner was created, including this owner. */
154	    public Integer getHouseholdMemberCount() {
155	        return this.householdMemberCount;
156	    }
157	
158	    public void setHouseholdMemberCount(Integer householdMemberCount) {
159	        this.householdMemberCount = householdMemberCount;
160	    }
161	
162	    /** True when this owner, at creation, shared an existing owner's last name and postcode
163	     *  but had a different telephone (a soft, non-hard duplicate). */
164	    public Boolean getPossibleDuplicate() {
165	        return this.possibleDuplicate;
166	    }
167	
168	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
169	        this.possibleDuplicate = possibleDuplicate;
170	    }
171	
172	    /** Id of the existing owner this owner possibly duplicates, when {@link #getPossibleDuplicate()}. */
173	    public Integer getPossibleDuplicateOf() {
174	        return this.possibleDuplicateOf;
175	    }
176	
177	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
178	        this.possibleDuplicateOf = possibleDuplicateOf;
179	    }
180	
181	    /** True when this owner's city already held between 40 and 49 owners (approaching the 50
182	     *  capacity limit) at the time it was created. */
183	    public Boolean getCapacityWarning() {
184	        return this.capacityWarning;
185	    }
186	
187	    public void setCapacityWarning(Boolean capacityWarning) {
188	        this.capacityWarning = capacityWarning;
189	    }
190	
191	    /** True once the owner has been soft-deleted; the row is retained but ignored by the
192	     *  create endpoint's duplicate and identity checks. False for a newly created owner. */
193	    public boolean isDeleted() {
194	        return this.deleted;
195	    }
196	
197	    public void setDeleted(boolean deleted) {
198	        this.deleted = deleted;
199	    }
200	
201	    public String getEmail() {
202	        return this.email;
203	    }
204	
205	    public void setEmail(String email) {
206	        this.email = email == null ? null : email.toLowerCase();
207	    }
208	
209	    public String getAddress() {
210	        return this.address;
211	    }
212	
213	    public void setAddress(String address) {
214	        this.flatAddress = AddressNormalizer.normalize(address);
215	        this.address = composeAddress();
216	    }
217	
218	    public String getAddressLine1() {
219	        return this.addressLine1;
220	    }
221	
222	    public void setAddressLine1(String addressLine1) {
223	        this.addressLine1 = AddressNormalizer.normalize(addressLine1);
224	        this.address = composeAddress();
225	    }
226	
227	    public String getAddressLine2() {
228	        return this.addressLine2;
229	    }
230	
231	    public void setAddressLine2(String addressLine2) {
232	        this.addressLine2 = AddressNormalizer.normalize(addressLine2);
233	        this.address = composeAddress();
234	    }
235	
236	    /** Prefer the structured lines when {@code addressLine1} is present (line 2 appended after a
237	     *  single space), otherwise fall back to the flat address, so all address readers stay consistent. */
238	    private String composeAddress() {
239	        if (this.addressLine1 == null || this.addressLine1.isBlank()) {
240	            return this.flatAddress;
241	        }
242	        return this.addressLine2 == null ? this.addressLine1 : this.addressLine1 + " " + this.addressLine2;
243	    }
244	
245	    public String getPostcode() {
246	        return this.postcode;
247	    }
248	
249	    public void setPostcode(String postcode) {
250	        this.postcode = postcode;
251	    }
252	
253	    public String getCity() {
254	        return this.city;
255	    }
256	
257	    public void setCity(String city) {
258	        this.city = city;
259	    }
260	
261	    public String getTelephone() {
262	        return this.telephone;
263	    }
264	
265	    public void setTelephone(String telephone) {
266	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
267	    }
268	
269	    protected Set<Pet> getPetsInternal() {
270	        if (this.pets == null) {
271	            this.pets = new HashSet<>();
272	        }
273	        return this.pets;
274	    }
275	
276	    protected void setPetsInternal(Set<Pet> pets) {
277	        this.pets = pets;
278	    }
279	
280	    public List<Pet> getPets() {
281	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
282	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
283	        return Collections.unmodifiableList(sortedPets);
284	    }
285	
286	    public void setPets(List<Pet> pets) {
287	        this.pets = new HashSet<>(pets);
288	    }
289	
290	    public void addPet(Pet pet) {
291	        getPetsInternal().add(pet);
292	        pet.setOwner(this);
293	    }
294	
295	    /**
296	     * Return the Pet with the given name, or null if none found for this Owner.
297	     *
298	     * @param name to test
299	     * @return true if pet name is already in use
300	     */
301	    public Pet getPet(String name) {
302	        return getPet(name, false);
303	    }
304	
305	    /**
306	     * Return the Pet with the given name, or null if none found for this Owner.
307	     *
308	     * @param name to test
309	     * @return true if pet name is already in use
310	     */
311	    public Pet getPet(String name, boolean ignoreNew) {
312	        name = name.toLowerCase();
313	        for (Pet pet : getPetsInternal()) {
314	            if (!ignoreNew || !pet.isNew()) {
315	                String compName = pet.getName();
316	                compName = compName.toLowerCase();
317	                if (compName.equals(name)) {
318	                    return pet;
319	                }
320	            }
321	        }
322	        return null;
323	    }
324	
325	    public Pet getPet(Integer petId) {
326	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
