25	/**
26	 * Emits an audit trail entry to the dedicated {@code AUDIT} logger whenever an
27	 * owner is first persisted, recording the assigned id, member id and
28	 * registration date. It also emits an immutable structured {@code OWNER_CREATED}
29	 * JSON event carrying the owner's current primary identifier (the member id).
30	 */
31	public class OwnerAuditListener {
32	
33	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
34	
35	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
36	
37	    /** Monotonically increasing sequence stamped on each structured create event. */
38	    private static final AtomicLong SEQ = new AtomicLong();
39	
40	    @PostPersist
41	    void onCreate(Owner owner) {
42	        int membershipLevel = MembershipLevel.of(MembershipLevel.points(owner.getNamesakeCount(),
43	            owner.getEmail(), owner.getHouseholdMemberCount(), owner.getRegistrationDate()));
44	        String ownerSegment = OwnerSegment.of(membershipLevel, Locality.of(owner.getCity(), owner.getPostcode()));
45	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
46	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
47	        AUDIT.info("{}", String.format(
48	            "{\"seq\":%d,\"ownerId\":%d,\"memberId\":\"%s\",\"membershipLevel\":%d,\"ownerSegment\":\"%s\",\"schemaVersion\":2,\"event\":\"OWNER_CREATED\"}",
49	            SEQ.incrementAndGet(), owner.getId(), owner.getMemberId(), membershipLevel, ownerSegment));
50	        NOTIFY.info("welcome ownerId={} memberId={}", owner.getId(), owner.getMemberId());
51	    }
52	}
