17	package org.springframework.samples.petclinic.rest.idempotency;
18	
19	import java.io.IOException;
20	import java.util.Map;
21	import java.util.concurrent.ConcurrentHashMap;
22	
23	import org.springframework.stereotype.Component;
24	import org.springframework.web.filter.OncePerRequestFilter;
25	import org.springframework.web.util.ContentCachingResponseWrapper;
26	
27	import jakarta.servlet.FilterChain;
28	import jakarta.servlet.ServletException;
29	import jakarta.servlet.http.HttpServletRequest;
30	import jakarta.servlet.http.HttpServletResponse;
31	
32	/**
33	 * Makes owner creation idempotent: a {@code POST /api/owners} that repeats an already-seen
34	 * {@code Idempotency-Key} replays the first response (as {@code 200 OK}) instead of creating
35	 * a duplicate.
36	 */
37	@Component
38	public class IdempotentCreateFilter extends OncePerRequestFilter {
39	
40	    private final Map<String, StoredResponse> responses = new ConcurrentHashMap<>();
41	
42	    @Override
43	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
44	                                    FilterChain chain) throws ServletException, IOException {
45	        String key = idempotencyKey(request);
46	        if (key == null) {
47	            chain.doFilter(request, response);
48	            return;
49	        }
50	        StoredResponse stored = responses.get(key);
51	        if (stored != null) {
52	            stored.replayTo(response);
53	            return;
54	        }
55	        ContentCachingResponseWrapper capture = new ContentCachingResponseWrapper(response);
56	        chain.doFilter(request, capture);
57	        if (isSuccessful(capture.getStatus())) {
58	            responses.put(key, StoredResponse.capturedFrom(capture));
59	        }
60	        capture.copyBodyToResponse();
61	    }
62	
63	    /** The create key when this is a {@code POST /api/owners} carrying one, else {@code null}. */
64	    private static String idempotencyKey(HttpServletRequest request) {
65	        if (!"POST".equalsIgnoreCase(request.getMethod())
66	                || !"/api/owners".equals(request.getRequestURI())) {
67	            return null;
68	        }
69	        return request.getHeader("Idempotency-Key");
70	    }
71	
72	    private static boolean isSuccessful(int status) {
73	        return status >= 200 && status < 300;
74	    }
75	}
