11	/**
12	 * Rejects a supplied postcode that is out of range for its city's region. Region ranges are fixed;
13	 * an unknown region, or a blank/malformed postcode (left to the field-level pattern), is accepted.
14	 */
15	public class ValidPostcodeValidator implements ConstraintValidator<ValidPostcode, OwnerFieldsDto> {
16	
17	    /** Region to its inclusive 4-digit postcode range {low, high}. */
18	    private static final Map<String, int[]> REGION_RANGE = Map.of(
19	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
20	
21	    @Override
22	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
23	        String postcode = owner == null ? null : owner.getPostcode();
24	        if (postcode == null || postcode.isBlank() || owner.getCity() == null) {
25	            return true;
26	        }
27	        int[] range = REGION_RANGE.get(Locality.of(owner.getCity()));
28	        if (range == null || !postcode.matches("\\d{4}")) {
29	            return true;
30	        }
31	        int value = Integer.parseInt(postcode);
32	        return value >= range[0] && value <= range[1];
33	    }
34	}
