17	
18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	import java.util.Set;
21	
22	/**
23	 * Rolls a registration date forward onto a business day: weekends and listed
24	 * public holidays are skipped, so the next non-holiday weekday is returned; a
25	 * plain weekday is returned unchanged.
26	 */
27	public final class BusinessDay {
28	
29	    private static final Set<LocalDate> HOLIDAYS = Set.of(
30	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
31	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
32	
33	    private BusinessDay() {
34	    }
35	
36	    /** Return {@code date}, or the next day that is neither a weekend nor a holiday. */
37	    public static LocalDate adjust(LocalDate date) {
38	        while (!isBusinessDay(date)) {
39	            date = date.plusDays(1);
40	        }
41	        return date;
42	    }
43	
44	    private static boolean isBusinessDay(LocalDate date) {
45	        DayOfWeek day = date.getDayOfWeek();
46	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
47	    }
48	}
