16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.util.Collection;
21	import java.util.HashSet;
22	import java.util.Set;
23	
24	/**
25	 * Builds an owner's unified {@code memberId}, formatted
26	 * {@code <REGION><FY><HASH8><CHK>}: the region derived from the owner's postcode,
27	 * the 2-digit fiscal year of the registration date, the first 8 upper-case hex
28	 * characters of {@code SHA-256(normalizedTelephone + lastName)} and a single Luhn
29	 * check digit over the digits of {@code <REGION><FY><HASH8>}, e.g.
30	 * {@code NSW261A2B3C4D5}.
31	 */
32	public final class MemberId {
33	
34	    private MemberId() {
35	    }
36	
37	    /**
38	     * @param owner          the owner being coded (postcode, telephone, last name and
39	     *                       registration date are used)
40	     * @param existingOwners the current owners, used only for collision handling
41	     * @return the formatted member id, e.g. {@code NSW261A2B3C4D5}
42	     */
43	    public static String of(Owner owner, Collection<Owner> existingOwners) {
44	        String region = Locality.of(owner.getCity(), owner.getPostcode()) + "V2";
45	        String base = region + String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100)
46	            + hash8(owner.getTelephone() + owner.getLastName());
47	        return deduplicate(base + CheckDigit.of(base), existingOwners);
48	    }
49	
50	    /** The leading {@code <REGION>} letters of a member id, or {@code "UNKNOWN"} when absent. */
51	    public static String regionOf(String memberId) {
52	        if (memberId == null) {
53	            return "UNKNOWN";
54	        }
55	        int i = 0;
56	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
57	            i++;
58	        }
59	        return i == 0 ? "UNKNOWN" : memberId.substring(0, i);
60	    }
61	
62	    /** Appends {@code -<n>} with the smallest {@code n >= 2} that avoids any existing
63	     *  owner's member id, or returns {@code base} unchanged when already unique. */
64	    private static String deduplicate(String base, Collection<Owner> existingOwners) {
65	        Set<String> taken = new HashSet<>();
66	        for (Owner existing : existingOwners) {
67	            taken.add(existing.getMemberId());
68	        }
69	        String unique = base;
70	        for (int n = 2; taken.contains(unique); n++) {
71	            unique = base + "-" + n;
72	        }
73	        return unique;
74	    }
75	
76	    private static String hash8(String value) {
77	        try {
78	            byte[] digest = MessageDigest.getInstance("SHA-256")
79	                .digest(value.getBytes(StandardCharsets.UTF_8));
80	            StringBuilder sb = new StringBuilder();
81	            for (int i = 0; i < 4; i++) {
82	                sb.append(String.format("%02X", digest[i]));
83	            }
84	            return sb.toString();
85	        }
86	        catch (java.security.NoSuchAlgorithmException e) {
87	            throw new IllegalStateException(e);
88	        }
89	    }
90	}
