22	/**
23	 * Derives an owner's duplicate-detection identity key: the SHA-256 hex of the normalized
24	 * telephone, lower-case email and {@link #soundex(String) soundex} of the last name, joined
25	 * with {@code '|'}. Two owners are the same identity only when this whole key matches.
26	 */
27	public final class IdentityKey {
28	
29	    /** Soundex code for A..Z: vowels, H, W and Y map to 0 (non-coding). */
30	    private static final String CODES = "01230120022455012623010202";
31	
32	    private IdentityKey() {
33	    }
34	
35	    /** SHA-256 hex over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. */
36	    public static String of(String telephone, String email, String lastName) {
37	        String key = "V2|" + (telephone == null ? "" : telephone) + "|"
38	            + (email == null ? "" : email.toLowerCase()) + "|"
39	            + soundex(lastName);
40	        try {
41	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
42	            StringBuilder sb = new StringBuilder(digest.length * 2);
43	            for (byte b : digest) {
44	                sb.append(String.format("%02x", b));
45	            }
46	            return sb.toString();
47	        }
48	        catch (NoSuchAlgorithmException e) {
49	            throw new IllegalStateException(e);
50	        }
51	    }
52	
53	    /** Standard Soundex code (an initial letter followed by three digits) for the given name. */
54	    public static String soundex(String value) {
55	        if (value == null) {
56	            return "";
57	        }
58	        StringBuilder letters = new StringBuilder();
59	        for (int i = 0; i < value.length(); i++) {
60	            char c = Character.toUpperCase(value.charAt(i));
61	            if (c >= 'A' && c <= 'Z') {
62	                letters.append(c);
63	            }
64	        }
65	        if (letters.length() == 0) {
66	            return "0000";
67	        }
68	        StringBuilder out = new StringBuilder().append(letters.charAt(0));
69	        int prev = code(letters.charAt(0));
70	        for (int i = 1; i < letters.length() && out.length() < 4; i++) {
71	            int c = code(letters.charAt(i));
72	            if (c > 0 && c != prev) {
73	                out.append((char) ('0' + c));
74	            }
75	            prev = c;
76	        }
77	        while (out.length() < 4) {
78	            out.append('0');
79	        }
80	        return out.toString();
81	    }
82	
83	    private static int code(char c) {
84	        return CODES.charAt(c - 'A') - '0';
85	    }
86	}
